	partition int32
	priority  priorityKey
}

type remotePriorityBacklogSet = map[remotePriorityBacklog]struct{}

var (
	errNoRecentPoller = status.Error(codes.FailedPrecondition, "no poller seen for task queue recently, worker may be down")

	// This is a fake error used to force reprocessing of task redirection as used by versioning.
	// Situations where we do this:
	// - after validateTasks maybe-validates a task (only local backlog)
	// - when userdata changes, on in-mem tasks (may be either sync or local backlog)
	// This must be an error type that taskReader will treat as transient and re-enqueue the task.
	errReprocessTask      = serviceerror.NewCanceled("reprocess task")
	errMatcherStopped     = serviceerror.NewCanceled("matcher stopped")
	errInternalMatchError = serviceerror.NewInternal("internal matcher error")
)

// newPriTaskMatcher returns a task matcher instance
func newPriTaskMatcher(
	tqCtx context.Context,
	config *taskQueueConfig,
	partition tqid.Partition,
	fwdr *priForwarder,
	client matchingservice.MatchingServiceClient,
	validator taskValidator,
	logger log.Logger,
	metricsHandler metrics.Handler,
	rateLimitManager *rateLimitManager,
	onRateLimited func(),
	markAlive func(),
) *priTaskMatcher {
	tm := &priTaskMatcher{
		config:                    config,
		data:                      newMatcherData(config, logger, clock.NewRealTimeSource(), fwdr != nil, rateLimitManager, onRateLimited),
		tqCtx:                     tqCtx,
		logger:                    logger,
		metricsHandler:            metricsHandler,
		partition:                 partition,
		fwdr:                      fwdr,
		client:                    client,
		validator:                 validator,
		rateLimitManager:          rateLimitManager,
		markAlive:                 markAlive,
		priorityBacklogForwarders: goro.NewKeyedSet[remotePriorityBacklog](tqCtx),
	}

	return tm
}

func (tm *priTaskMatcher) Start() {
	policy := backoff.NewExponentialRetryPolicy(time.Second).
		WithMaximumInterval(tm.config.BacklogTaskForwardTimeout()).
		WithExpirationInterval(backoff.NoInterval)
	validatorRetrier := backoff.NewRetrier(policy, clock.NewRealTimeSource())
	go tm.validateTasks(validatorRetrier)

	if tm.fwdr == nil {
		return
	}

	lim := quotas.NewDefaultOutgoingRateLimiter(tm.config.ForwarderMaxRatePerSecond)

	// Forwarders share a synchronized per-task validation cache. Each worker owns
	// its retrier so one worker's success cannot reset another worker's backoff.
	for range tm.config.ForwarderMaxOutstandingTasks() {
		retrier := backoff.NewRetrier(policy, clock.NewRealTimeSource())
		go tm.forwardTasks(lim, retrier)
	}

	if normal, ok := tm.partition.(*tqid.NormalPartition); ok { // always true here, sticky has nil tm.fwdr
		degree := tm.config.ForwarderMaxChildrenPerNode()
		if parent, err := normal.ParentPartition(degree); err == nil {
			for range tm.config.ForwarderMaxOutstandingPolls() {
				go tm.forwardPolls(tm.tqCtx, 0, pollForwarderPriority, parentPollForwarder, parent)
			}
		}
	}
}

func (tm *priTaskMatcher) Stop() {
	tm.data.Stop()

	tm.priorityBacklogForwarders.Sync(nil, nil)

	// When we're stopping, sync tasks and pollers will be cancelled by tqCtx being canceled.
	// Backlog tasks held in this matcher will be dropped. That's okay if we're stopping the
	// whole partition, or for tasks that came from this partition's readers. The exception is
	// backlog tasks that were redirected from another versioned queue (or the default). To
	// handle those, the caller of Stop should also call ReprocessRedirectedTasksAfterStop
	// when applicable.
}

func (tm *priTaskMatcher) forwardTasks(lim quotas.RateLimiter, retrier backoff.Retrier) {
	ctxs := []context.Context{tm.tqCtx}
	poller := waitingPoller{taskForwarderType: parentTaskForwarder}
	skipLimiter := false
	var err error
	for {
		if !skipLimiter && lim.Wait(tm.tqCtx) != nil {
			return
		}

		res := tm.data.EnqueuePollerAndWait(ctxs, &poller)
		if res.ctxErr != nil {
			return // task queue closing
		}
		if !softassert.That(tm.logger, res.task != nil, "expected a task from match") {
			continue
		}

		skipLimiter, err = tm.forwardTask(res.task)

		// backoff on resource exhausted errors
		if common.IsResourceExhausted(err) {
			util.InterruptibleSleep(tm.tqCtx, retrier.NextBackOff(err))
		} else {
			retrier.Reset()
		}
	}
}

func (tm *priTaskMatcher) forwardTask(task *internalTask) (bool, error) {
	var ctx context.Context
	var cancel context.CancelFunc
	if task.forwardCtx != nil {
		// Use sync match context if we have it (for deadline, headers, etc.)
		// TODO(pri): does it make sense to subtract 1s from the context deadline here?
		// Also arrange for this to be canceled on tqCtx closing.
		ctx, cancel = context.WithCancel(task.forwardCtx)
		stop := context.AfterFunc(tm.tqCtx, cancel)
		defer cancel()
		defer stop()
	} else {
		// Task is from local backlog.

		// Before we forward, ask task validator. This will happen every BacklogTaskForwardTimeout
		// to the head of the backlog, which is what taskValidator expects.
		maybeValid := tm.validator.maybeValidate(task.event.AllocatedTaskInfo, tm.fwdr.partition.TaskType())
		if !maybeValid {
			// consider this task expired while processing.
			task.finish(getDroppedTaskExpiryReason(task))

			// Stay alive as long as we're invalidating tasks
			tm.markAlive()

			return true, nil
		}

		// Add a timeout for forwarding.
		// Note that this does not block local match of other local backlog tasks.
		ctx, cancel = context.WithTimeout(tm.tqCtx, tm.config.BacklogTaskForwardTimeout())
		defer cancel()
	}

	if task.isQuery() {
		res, err := tm.fwdr.ForwardQueryTask(ctx, task)
		task.finishForward(res, err)
		return false, err
	}

	if task.isNexus() {
		res, err := tm.fwdr.ForwardNexusTask(ctx, task)
		task.finishForward(res, err)
		return false, err
	}

	// normal wf/activity task
	err := tm.fwdr.ForwardTask(ctx, task)
	task.finishForward(nil, err)

	return false, err
}

func (tm *priTaskMatcher) takeValidatorBatch(ctxs []context.Context, n int) ([]*internalTask, error) {
	res := tm.data.EnqueuePollerAndWait(ctxs, &waitingPoller{taskForwarderType: validatorTaskForwarder})
	if res.ctxErr != nil {
		return nil, res.ctxErr
	}
	tasks := []*internalTask{res.task}
	for len(tasks) < n {
		more := tm.data.MatchPollerImmediately(&waitingPoller{taskForwarderType: validatorTaskForwarder})
		if more == nil || more.task == nil {
			break
		}
		tasks = append(tasks, more.task)
	}
	return tasks, nil
}

func (tm *priTaskMatcher) validateTasks(retrier backoff.Retrier) {
	ctxs := []context.Context{tm.tqCtx}
	for {
		// Avoid evicting validation history because a batch exceeds the cache capacity.
		n := min(taskValidatorCacheMaxSize, max(1, tm.config.ValidatorBatchSize()))
		tasks, err := tm.takeValidatorBatch(ctxs, n)
		if err != nil {
			return // task queue closing
		}
		if len(tasks) == 0 {
			continue
		}

		var anyInvalid atomic.Bool
		var wg sync.WaitGroup
		for _, task := range tasks {
			if !softassert.That(tm.logger, task.forwardCtx == nil, "expected non-forwarded task") ||
				!softassert.That(tm.logger, !task.isSyncMatchTask(), "expected non-sync match task") ||
				!softassert.That(tm.logger, task.source == enumsspb.TASK_SOURCE_DB_BACKLOG, "expected backlog task") {
				continue
			}
			wg.Go(func() {
				maybeValid := tm.validator == nil || tm.validator.maybeValidate(task.event.AllocatedTaskInfo, tm.partition.TaskType())
				if !maybeValid {
					// We found an invalid one, complete it and go back for another batch immediately.
					task.finish(getDroppedTaskExpiryReason(task))

					// Stay alive as long as we're invalidating tasks
					tm.markAlive()
					anyInvalid.Store(true)
				} else {
					// Task was valid, put it back and slow down checking if the whole batch is valid.
					task.finish(errReprocessTask)
				}
			})

