+			DeploymentVersion: common.CloneProto(previous.GetDeploymentVersion()),
+			Percentage:        previous.GetPercentage(),
+			CreateTimestamp:   clock,
+		})
+		break
+	}
+	data.RevisionNumber++
+	return data, nil
+}
