	workflowType string,
) (*persistencespb.WorkflowTypeVersioningData, error) {
	if clock == nil {
		return nil, errWorkflowTypeRoutingNoClock
	}
	data = cloneWorkflowTypeVersioningData(data)
	for _, rule := range data.GetRules() {
		if rule.GetWorkflowType() == workflowType && rule.GetDeleteTimestamp() == nil {
			rule.DeleteTimestamp = clock
		}
	}
	data.RevisionNumber++
	return data, nil
}

// RollbackWorkflowTypeVersioningRule tombstones the active rule for a workflow type and restores
// the rule that was active before it. If no previous rule exists, the workflow type falls back to
// the task queue's current/ramping routing.
func RollbackWorkflowTypeVersioningRule(
	clock *hlc.Clock,
	data *persistencespb.WorkflowTypeVersioningData,
	workflowType string,
) (*persistencespb.WorkflowTypeVersioningData, error) {
	if clock == nil {
		return nil, errWorkflowTypeRoutingNoClock
	}

	data = cloneWorkflowTypeVersioningData(data)
	activeIndex := -1
	for i, rule := range data.GetRules() {
		if rule.GetWorkflowType() == workflowType && rule.GetDeleteTimestamp() == nil {
			activeIndex = i
		}
	}
	if activeIndex == -1 {
		return data, nil
	}

	data.Rules[activeIndex].DeleteTimestamp = clock
	for i := activeIndex - 1; i >= 0; i-- {
		previous := data.GetRules()[i]
		if previous.GetWorkflowType() != workflowType {
			continue
		}
		data.Rules = append(data.Rules, &persistencespb.WorkflowTypeVersioningRule{
			WorkflowType:      workflowType,
			DeploymentVersion: common.CloneProto(previous.GetDeploymentVersion()),
			Percentage:        previous.GetPercentage(),
			CreateTimestamp:   clock,
		})
		break
	}
	data.RevisionNumber++
	return data, nil
}

// FindActiveWorkflowTypeVersioningRule returns the last active rule for a workflow type.
func FindActiveWorkflowTypeVersioningRule(
	data *persistencespb.WorkflowTypeVersioningData,
	workflowType string,
) *persistencespb.WorkflowTypeVersioningRule {
	var active *persistencespb.WorkflowTypeVersioningRule
	for _, rule := range data.GetRules() {
		if rule.GetWorkflowType() == workflowType && rule.GetDeleteTimestamp() == nil {
			active = rule
		}
	}
	return active
}

// SelectWorkflowTypeVersioningRule picks the rule target for one workflow execution. It returns
// nil when the execution should use the task queue's normal current/ramping routing.
func SelectWorkflowTypeVersioningRule(
	data *persistencespb.WorkflowTypeVersioningData,
	workflowType string,
	workflowID string,
) *persistencespb.WorkflowTypeVersioningRule {
	rule := FindActiveWorkflowTypeVersioningRule(data, workflowType)
	if rule == nil {
		return nil
	}

	percentage := rule.GetPercentage()
	if percentage <= 0 {
		return nil
	}
	if percentage < 100 {
		threshold := calcWorkflowTypeRampThreshold(workflowType, workflowID)
		if threshold > float64(percentage) {
			return nil
		}
	}
	return rule
}

// FindTargetDeploymentVersionAndRevisionNumberForWorkflowTask applies workflow type routing
// before falling back to the task queue's current/ramping routing.
func FindTargetDeploymentVersionAndRevisionNumberForWorkflowTask(
	current *deploymentspb.WorkerDeploymentVersion,
	currentRevisionNumber int64,
	ramping *deploymentspb.WorkerDeploymentVersion,
	rampingPercentage float32,
	rampingRevisionNumber int64,
	workflowType string,
	workflowID string,
	useRampingVersion bool,
	workflowTypeVersioning *persistencespb.WorkflowTypeVersioningData,
) (*deploymentspb.WorkerDeploymentVersion, int64) {
	if rule := SelectWorkflowTypeVersioningRule(workflowTypeVersioning, workflowType, workflowID); rule != nil {
		return rule.GetDeploymentVersion(), workflowTypeVersioning.GetRevisionNumber()
	}
	return FindTargetDeploymentVersionAndRevisionNumberForWorkflowID(
		current,
		currentRevisionNumber,
		ramping,
		rampingPercentage,
		rampingRevisionNumber,
		workflowID,
		useRampingVersion,
	)
}

func calcWorkflowTypeRampThreshold(workflowType, workflowID string) float64 {
	h := farm.Fingerprint32([]byte(workflowType + "\x00" + workflowID))
	return 100 * (float64(h) / (float64(math.MaxUint32) + 1))
}

func cloneWorkflowTypeVersioningData(data *persistencespb.WorkflowTypeVersioningData) *persistencespb.WorkflowTypeVersioningData {
	if data == nil {
		return &persistencespb.WorkflowTypeVersioningData{}
	}
	return common.CloneProto(data)
}

