func (s *transferQueueActiveTaskExecutorSuite) createAddWorkflowTaskRequest(
	task *tasks.WorkflowTask,
	mutableState historyi.MutableState,
) gomock.Matcher {
	taskQueue := &taskqueuepb.TaskQueue{
